import numpy as np
import copy

# Make a deep copy
output = [row[:] for row in grid]

# Function to find frames
def find_and_fill_frames(grid, color):
    """Find hollow frames of given color and fill interiors with 9"""
    cells = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                cells.append((r, c))

    if not cells:
        return

    # Find bounding box
    rows = [c[0] for c in cells]
    cols = [c[1] for c in cells]
    r_min, r_max = min(rows), max(rows)
    c_min, c_max = min(cols), max(cols)

    # Fill only the interior (not the border)
    for r in range(r_min + 1, r_max):
        for c in range(c_min + 1, c_max):
            if grid[r][c] == color:
                output[r][c] = 9
            elif grid[r][c] != 9:  # Fill non-9 content inside with 9
                output[r][c] = 9

# Apply to each non-9 color
for color in [3, 0, 6]:
    find_and_fill_frames(output, color)

print("Output:")
for row in output:
    print(row)

import numpy as np
import copy
import json

def fill_solid(grid):
    """Fill hollow frames with their frame color"""
    output = copy.deepcopy(grid)

    # Find and fill 0-color frame
    # Rows 2-7, Cols 1-6
    for r in range(2, 8):
        for c in range(1, 7):
            if output[r][c] == 9:
                output[r][c] = 0

    # Find and fill 3-color frame
    # Rows 1-7, Cols 14-20
    for r in range(1, 8):
        for c in range(14, 21):
            if output[r][c] == 9:
                output[r][c] = 3

    # Find and fill 6-color frame
    # Rows 5-7, Cols 9-11
    for r in range(5, 8):
        for c in range(9, 12):
            if output[r][c] == 9:
                output[r][c] = 6

    return output

